const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const app=$('#app');
const state={user:null,settings:{currency:'$'},cart:{},page:'home',cleanup:null};
const PERM_GROUPS={
  'Tableau de bord':[['dashboard.member','Dashboard membre'],['ranking.view','Classement'],['widgets.manage','Créer / modifier les widgets']],
  'Groupes & stock':[['groups.view','Voir les groupes'],['groups.edit','Modifier les groupes'],['stock.view','Voir le stock'],['stock.edit','Modifier le stock'],['categories.edit','Gérer les catégories']],
  'Commandes & finances':[['orders.view','Voir les commandes'],['orders.edit','Gérer les commandes'],['orders.history','Voir l’historique des commandes'],['finance.view','Voir les finances'],['finance.edit','Modifier le cash']],
  'Communication':[['messages.manage','Gérer les messages'],['appointments.manage','Gérer les rendez-vous'],['announcements.edit','Publier des annonces']],
  'Administration':[['users.view','Voir les comptes complets'],['users.info.view','Voir les informations des comptes'],['users.password.view','Voir les mots de passe enregistrés'],['users.edit','Modifier les comptes'],['roles.edit','Modifier les rôles'],['logs.view','Voir les logs'],['settings.edit','Modifier les paramètres']],
  'Boutique':[['shop.access','Accéder à la boutique']]
};
const ORDER_STATUSES=['Nouvelle','En attente','Acceptée','Préparation','Prête','Terminée','Refusée','Annulée'];
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function fmt(n){return new Intl.NumberFormat('fr-FR').format(Number(n||0))+' '+(state.settings.currency||'$')}
function dt(v){if(!v)return '—';try{return new Date(v).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}catch{return v}}
function dateOnly(v){if(!v)return '—';try{return new Date(v).toLocaleDateString('fr-FR')}catch{return v}}
function can(p){return !!state.user && (state.user.role?.slug==='super-admin'||!!state.user.permissions?.[p])}
function isClient(){return state.user?.role?.slug==='client'}
function isSuper(){return state.user?.role?.slug==='super-admin'}
async function api(path,method='GET',data){const o={method,headers:{}};if(data!==undefined){o.headers['Content-Type']='application/json';o.body=JSON.stringify(data)}const r=await fetch('/api/'+path,o);const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Erreur');return j}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}
function modal(html){const b=document.createElement('div');b.className='modal-back';b.innerHTML='<div class="modal"><div class="line" style="margin-bottom:10px"><span></span><button type="button" class="btn small close-modal">Fermer</button></div>'+html+'</div>';document.body.appendChild(b);$('.close-modal',b).onclick=()=>b.remove();b.addEventListener('click',e=>{if(e.target===b)b.remove()});return b}
function parsePhones(v){return String(v||'').split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean).slice(0,8)}
async function fileToDataUrl(f){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)})}
function cleanup(){if(state.cleanup){try{state.cleanup()}catch{}state.cleanup=null}}

async function boot(){try{const m=await api('me');state.user=m.user;if(!state.user)return login();const b=await api('bootstrap');state.user=b.user;state.settings=b.settings||state.settings;shell()}catch{login()}}
function login(){cleanup();app.innerHTML=`<div class="login"><div class="login-card"><div class="brandmark">BA</div><div class="eyebrow">BLACK ACE PRIVATE NETWORK</div><h1>Connexion</h1><p class="muted">Utilise ton nom d'utilisateur et ton mot de passe.</p><form id="loginForm" class="stack"><input class="input" name="username" autocomplete="username" placeholder="Nom d'utilisateur" required><input class="input" name="password" type="password" autocomplete="current-password" placeholder="Mot de passe" required><button class="btn gold">Se connecter</button><div id="loginErr" class="muted"></div></form></div></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('login','POST',{username:f.get('username'),password:f.get('password')});boot()}catch(err){$('#loginErr').textContent=err.message}}}
function navItems(){const n=[['home','⌂','Accueil']];if(isClient()){n.push(['shop','◇','Boutique'],['orders','▣','Commandes'],['announcements','◈','Annonces'],['messages','✉','Messages'],['appointments','⌖','Rendez-vous'])}else{n.push(['manage','◆','Gestion'],['messages','✉','Messages'],['appointments','⌖','Rendez-vous'],['game','●','Flappy Ace']);if(can('users.view')||can('roles.edit')||can('settings.edit')||can('logs.view')||can('widgets.manage'))n.push(['admin','⚙','Admin'])}return n}
function shell(){cleanup();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${esc(state.settings.logoText||'BA')}</div><div><b>${esc(state.settings.appName||'BLACK ACE')}</b><div class="muted" style="font-size:11px">${esc(state.settings.tagline||'Private Network')}</div></div></div><nav class="nav">${navItems().map(([id,ic,l])=>`<button data-page="${id}" class="${state.page===id?'active':''}"><span>${ic}</span>${l}</button>`).join('')}</nav><div class="sidebar-foot"><div class="line"><div><b>${esc(state.user.displayName)}</b><div class="muted" style="font-size:11px">${esc(state.user.role?.name||'')}</div></div><button id="logout" class="btn small">↪</button></div></div></aside><main class="content"><div class="topbar"><div><div class="eyebrow">BLACK ACE</div><h1 class="page-title" id="pageTitle">Accueil</h1></div><div class="top-actions"><span class="muted">@${esc(state.user.username)}</span><div class="avatar">${esc((state.user.displayName||'B').slice(0,1).toUpperCase())}</div></div></div><div id="view"></div></main></div>`;$$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#logout').onclick=async()=>{await api('logout','POST');state.user=null;login()};go(state.page,true)}
async function go(page,keep=false){cleanup();state.page=page;$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const titles={home:'Accueil',shop:'Boutique',orders:'Commandes',announcements:'Annonces',manage:'Gestion',messages:'Messages',appointments:'Rendez-vous',game:'Flappy Ace',admin:'Administration'};$('#pageTitle').textContent=titles[page]||page;const c=$('#view');c.innerHTML='<div class="panel muted">Chargement…</div>';try{if(page==='home')await home(c);else if(page==='shop')await shop(c);else if(page==='orders')await orders(c);else if(page==='announcements')await clientAnnouncements(c);else if(page==='manage')await manage(c);else if(page==='messages')await messages(c);else if(page==='appointments')await appointments(c);else if(page==='game')game(c);else if(page==='admin')await admin(c)}catch(e){c.innerHTML=`<div class="panel"><b>Erreur</b><p class="muted">${esc(e.message)}</p></div>`}}

async function home(c){const [d,w]=await Promise.all([api('dashboard'),api('widgets').catch(()=>[])]);if(d.type==='client')return clientHome(c,d,w);memberHome(c,d,w)}
function widgetCards(w){if(!w?.length)return '';return `<div class="section"><div class="section-head"><h3>Widgets</h3></div><div class="widget-grid">${w.map(x=>`<div class="widget-card"><div class="muted">${esc(x.icon||'◆')} ${esc(x.title)}</div><div class="value">${esc(x.value)}</div><div class="muted">${esc(x.subtitle||'')}</div></div>`).join('')}</div></div>`}
async function clientHome(c,d,w){const p=await api('profile');c.innerHTML=`<div class="profile-grid"><div><div class="grid stats"><div class="panel stat"><span>Commandes</span><b>${d.orders}</b></div><div class="panel stat"><span>En cours</span><b>${d.pending}</b></div><div class="panel stat"><span>Total validé</span><b>${fmt(d.totalSpent)}</b></div><div class="panel stat"><span>Prochain RDV</span><b style="font-size:16px">${d.nextAppointment?dt(d.nextAppointment.scheduledAt):'Aucun'}</b></div></div>${widgetCards(w)}<div class="section panel"><div class="section-head"><div><div class="eyebrow">PROFIL CLIENT</div><h2 style="margin:4px 0">Mes informations</h2></div><button id="editProfile" class="btn gold">Modifier</button></div><div class="cred-grid"><div class="cred"><small>ID compte</small><code>${esc(p.accountCode||p.id)}</code></div><div class="cred"><small>Nom d'utilisateur</small><code>${esc(p.username)}</code></div><div class="cred"><small>Mot de passe</small><code>${esc(p.passwordLabel||'••••••••')}</code></div></div><div class="section"><div class="line wrap"><span class="muted">Nom</span><b>${esc(p.displayName)}</b></div><div class="line wrap" style="margin-top:8px"><span class="muted">Groupe</span><b>${esc(p.group?.name||'Non renseigné')}</b></div><div class="line wrap" style="margin-top:8px"><span class="muted">Téléphones</span><b>${esc((p.phones||[]).join(' • ')||'Aucun')}</b></div></div></div></div><div class="panel"><div class="eyebrow">COMPTE</div><h3>Accès personnel</h3><p class="muted">Tu peux modifier ton nom, ton groupe, plusieurs numéros et ton mot de passe sans passer par un administrateur.</p><div class="status ok">Compte actif</div></div></div>`;$('#editProfile').onclick=()=>profileModal(p)}
function profileModal(p){const d=modal(`<h2>Modifier mon profil</h2><form class="stack"><label>ID compte<input class="input" name="accountCode" value="${esc(p.accountCode||p.id)}" required></label><label>Nom affiché<input class="input" name="displayName" value="${esc(p.displayName)}"></label><label>Nom du groupe<input class="input" name="groupName" value="${esc(p.group?.name||'')}"></label><label>Numéros de téléphone <span class="muted">(un par ligne)</span><textarea class="input" name="phones">${esc((p.phones||[]).join('\n'))}</textarea></label><label>Nouveau mot de passe<input class="input" type="password" name="password" placeholder="Laisser vide pour conserver"></label><button class="btn gold">Enregistrer</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('profile','PUT',{accountCode:f.get('accountCode'),displayName:f.get('displayName'),groupName:f.get('groupName'),phones:parsePhones(f.get('phones')),password:f.get('password')});d.remove();toast('Profil mis à jour');boot()}catch(err){toast(err.message)}}}
function memberHome(c,d,w){c.innerHTML=`<div class="grid stats"><div class="panel stat"><span>Cash global</span><b>${fmt(d.cash)}</b></div><div class="panel stat"><span>Stock total</span><b>${d.stockItems}</b></div><div class="panel stat"><span>Commandes actives</span><b>${d.pendingOrders}</b></div><div class="panel stat"><span>RDV actifs</span><b>${d.appointments}</b></div></div>${widgetCards(w)}<div class="section split"><div class="panel"><div class="section-head"><h3>Classement groupes</h3><div class="tabs"><button class="tab active" data-rank="week">Semaine</button><button class="tab" data-rank="month">Mois</button></div></div><div id="ranking"></div></div><div class="panel"><div class="section-head"><h3>Groupes présents</h3><span class="pill">${d.groups.length}</span></div><div class="stack">${d.groups.slice(0,8).map(g=>`<div class="line wrap"><div><b>${esc(g.name)}</b><div class="muted" style="font-size:12px">${esc(g.relation||'')} • ${esc(g.status||'')}</div></div><span class="muted">${esc((g.contacts||[]).join(' • ')||'—')}</span></div>`).join('')}</div></div></div>`;function rr(rows){const top=rows.slice(0,3),rest=rows.slice(3);$('#ranking').innerHTML=rows.length?`<div class="ranking"><div class="podium">${top.map((r,i)=>`<div class="rank-card ${i===0?'first':''}"><div class="place">${i+1}</div><b>${esc(r.name)}</b><div>${fmt(r.total)}</div><span class="muted">${r.orders} commande(s)</span></div>`).join('')}</div>${rest.length?`<div class="rank-rest">${rest.map((r,i)=>`<div class="rank-row"><b>#${i+4}</b><span>${esc(r.name)}</span><b>${fmt(r.total)}</b><span class="muted">${r.orders} cmd</span></div>`).join('')}</div>`:''}</div>`:'<p class="muted">Aucune vente terminée sur cette période.</p>'}rr(d.weekRanking);$$('[data-rank]').forEach(b=>b.onclick=()=>{$$('[data-rank]').forEach(x=>x.classList.remove('active'));b.classList.add('active');rr(b.dataset.rank==='week'?d.weekRanking:d.monthRanking)})}

async function shop(c){const b=await api('bootstrap');const cats=b.categories,prods=b.products;c.innerHTML=`<div class="section-head"><div><h2 style="margin:0">Catalogue</h2><p class="muted">Saisis directement la quantité souhaitée.</p></div><button id="cartBtn" class="btn gold">Panier <span id="cartCount"></span></button></div><div class="tabs"><button class="tab active" data-cat="all">Tout</button>${cats.map(x=>`<button class="tab" data-cat="${x.id}" style="--cat-accent:${esc(x.color||'#D4AF37')}">${esc(x.icon)} ${esc(x.name)}</button>`).join('')}</div><div id="products" class="cards shop-grid"></div>`;const render=cat=>{const conf=cats.find(x=>x.id===cat);const grid=$('#products');grid.style.setProperty('--shop-cols',conf?.layoutCols||3);grid.innerHTML=prods.filter(p=>cat==='all'||p.categoryId===cat).map(p=>`<div class="panel product">${p.image?`<div class="product-img"><img src="${p.image}" alt=""></div>`:`<div class="product-img">BLACK ACE</div>`}<div><b>${esc(p.name)}</b><div class="muted">${esc(p.description||'')}</div></div><div class="line"><span>${fmt(p.sellPrice)}</span><span class="muted">Stock ${p.stock}</span></div><div class="line"><input class="input qty" style="max-width:110px" type="number" min="1" max="9999" value="1" data-id="${p.id}"><button class="btn gold add" data-id="${p.id}">Ajouter</button></div></div>`).join('')||'<div class="panel muted">Aucun objet.</div>';$$('.qty').forEach(x=>x.addEventListener('blur',()=>{x.value=Math.max(1,Math.min(9999,parseInt(x.value,10)||1))}));$$('.add').forEach(x=>x.onclick=()=>{const q=Math.max(1,Math.min(9999,parseInt($(`.qty[data-id="${x.dataset.id}"]`).value,10)||1));state.cart[x.dataset.id]=(state.cart[x.dataset.id]||0)+q;cartCount();toast('Ajouté au panier')})};function cartCount(){$('#cartCount').textContent='('+Object.values(state.cart).reduce((a,b)=>a+Number(b||0),0)+')'}render('all');cartCount();$$('[data-cat]').forEach(btn=>btn.onclick=()=>{$$('[data-cat]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');render(btn.dataset.cat);cartCount()});$('#cartBtn').onclick=()=>cartModal(prods)}
function cartModal(prods){const d=modal(`<h2>Panier</h2><div id="cartRows" class="stack"></div><textarea id="orderNote" class="input" placeholder="Note pour Black Ace"></textarea><div class="line"><b>Total</b><b id="cartTotal"></b></div><button id="sendOrder" class="btn gold">Valider la commande</button>`);function total(){const rows=Object.entries(state.cart).map(([id,q])=>({p:prods.find(x=>x.id===id),q:Number(q||0)})).filter(x=>x.p&&x.q>0);$('#cartTotal',d).textContent=fmt(rows.reduce((s,x)=>s+x.p.sellPrice*x.q,0));$('#sendOrder',d).disabled=!rows.length}function render(){const rows=Object.entries(state.cart).map(([id,q])=>({p:prods.find(x=>x.id===id),q:Number(q||1)})).filter(x=>x.p);$('#cartRows',d).innerHTML=rows.length?rows.map(x=>`<div class="panel flat"><div class="line"><b>${esc(x.p.name)}</b><button class="btn small danger remove" data-id="${x.p.id}">Supprimer</button></div><div class="line" style="margin-top:8px"><input class="input cart-qty" style="max-width:130px" type="number" min="1" max="9999" value="${x.q}" data-id="${x.p.id}"><b class="line-total" data-id="${x.p.id}">${fmt(x.p.sellPrice*x.q)}</b></div></div>`).join(''):'<p class="muted">Panier vide.</p>';$$('.cart-qty',d).forEach(i=>{i.addEventListener('input',()=>{const raw=i.value.trim();if(raw==='')return;const q=Math.max(1,Math.min(9999,parseInt(raw,10)||1));state.cart[i.dataset.id]=q;const prod=prods.find(x=>x.id===i.dataset.id);const out=$(`.line-total[data-id="${i.dataset.id}"]`,d);if(out&&prod)out.textContent=fmt(prod.sellPrice*q);total()});i.addEventListener('blur',()=>{const q=Math.max(1,Math.min(9999,parseInt(i.value,10)||1));i.value=q;state.cart[i.dataset.id]=q;total()})});$$('.remove',d).forEach(b=>b.onclick=()=>{delete state.cart[b.dataset.id];render()});total()}render();$('#sendOrder',d).onclick=async()=>{const items=Object.entries(state.cart).map(([productId,quantity])=>({productId,quantity:Number(quantity)}));await api('orders','POST',{items,note:$('#orderNote',d).value});state.cart={};d.remove();toast('Commande envoyée');go('orders')}}

async function orders(c){const rows=await api('orders');c.innerHTML=`<div class="section-head"><div><h2 style="margin:0">${isClient()?'Suivi de mes commandes':'Commandes actives'}</h2><p class="muted">${isClient()?'Les commandes terminées restent visibles ici.':'Les commandes terminées, refusées et annulées partent dans Historique.'}</p></div></div><div class="stack">${rows.map(o=>`<div class="panel"><div class="line wrap"><div><b>${esc(o.number)}</b><div class="muted">${isClient()?'':esc(o.clientName)+' • '+esc(o.groupName)+' • '}${dt(o.createdAt)}</div></div><span class="status">${esc(o.status)}</span></div>${!isClient()?`<div class="section line wrap"><span class="muted">Prise en charge</span><b>${o.takenByName?esc(o.takenByName)+' (@'+esc(o.takenByUsername)+') • '+esc(o.takenByRole):'Personne'}</b></div>`:''}<div class="section">${o.items.map(i=>`<div class="line"><span>${esc(i.name)} × ${i.quantity}</span><b>${fmt(i.price*i.quantity)}</b></div>`).join('')}</div><div class="line" style="margin-top:12px"><b>Total</b><b>${fmt(o.total)}</b></div>${o.note?`<p class="muted">Note : ${esc(o.note)}</p>`:''}<div class="section"><div class="eyebrow">SUIVI</div>${(o.history||[]).map(h=>`<div class="line" style="margin-top:5px"><span>${esc(h.status)}</span><span class="muted">${dt(h.at)}</span></div>`).join('')}</div>${!isClient()&&can('orders.edit')?`<div class="section line wrap">${!o.takenBy?`<button class="btn take-order" data-id="${o.id}">Prendre en charge</button>`:''}<select class="input order-status" data-id="${o.id}" style="max-width:240px">${ORDER_STATUSES.map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select><button class="btn gold save-order" data-id="${o.id}">Mettre à jour</button></div>`:''}</div>`).join('')||'<div class="panel muted">Aucune commande active.</div>'}`;$$('.take-order').forEach(b=>b.onclick=async()=>{await api('orders','PUT',{id:b.dataset.id,take:true});toast('Commande prise en charge');orders(c)});$$('.save-order').forEach(b=>b.onclick=async()=>{const s=$(`.order-status[data-id="${b.dataset.id}"]`).value;await api('orders','PUT',{id:b.dataset.id,status:s});toast(s==='Terminée'?'Commande déplacée dans Historique':'Commande mise à jour');orders(c)})}

async function manage(c){if(isClient())return;const tabs=[];if(can('groups.view'))tabs.push(['groups','Groupes']);if(can('orders.view'))tabs.push(['orders','Commandes']);if(can('orders.history'))tabs.push(['history','Historique']);if(can('finance.view'))tabs.push(['finance','Cash']);if(can('stock.view')||can('categories.edit')||isSuper())tabs.push(['catalog','Stock / objets']);if(can('announcements.edit'))tabs.push(['ann','Annonces']);if(!tabs.length){c.innerHTML='<div class="panel muted">Aucun accès de gestion.</div>';return}c.innerHTML=`<div class="tabs">${tabs.map((x,i)=>`<button class="tab ${i===0?'active':''}" data-mtab="${x[0]}">${x[1]}</button>`).join('')}</div><div id="manageBody"></div>`;const body=$('#manageBody');async function load(t){$$('[data-mtab]').forEach(b=>b.classList.toggle('active',b.dataset.mtab===t));if(t==='groups')await groupsView(body);if(t==='orders')await orders(body);if(t==='history')await orderHistoryView(body);if(t==='finance')await financeView(body);if(t==='catalog')await catalogView(body);if(t==='ann')await announcementsView(body)}$$('[data-mtab]').forEach(b=>b.onclick=()=>load(b.dataset.mtab));await load(tabs[0][0])}
async function orderHistoryView(c){const data=await api('order-history');c.innerHTML=`<div class="section-head"><div><h3>Historique des commandes</h3><p class="muted">Recherche un groupe pour n’afficher que ses commandes.</p></div></div><div class="panel"><div class="line wrap"><input id="histQ" class="input" style="max-width:300px" placeholder="N° commande, client, objet…"><select id="histGroup" class="input" style="max-width:280px"><option value="">Tous les groupes</option>${data.groups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select><button id="histSearch" class="btn gold">Rechercher</button><button id="histReset" class="btn">Réinitialiser</button></div></div><div id="histRows" class="section"></div>`;async function load(){const qs=new URLSearchParams();if($('#histQ').value.trim())qs.set('q',$('#histQ').value.trim());if($('#histGroup').value)qs.set('groupId',$('#histGroup').value);const r=await api('order-history?'+qs.toString());$('#histRows').innerHTML=r.orders.map(o=>`<div class="panel" style="margin-bottom:10px"><div class="line wrap"><div><b>${esc(o.number)}</b><div class="muted">${esc(o.groupName)} • ${esc(o.clientName)} • ${dt(o.createdAt)}</div><div class="muted">Pris en charge par : ${o.takenByName?esc(o.takenByName)+' (@'+esc(o.takenByUsername)+') • '+esc(o.takenByRole):'Non attribuée'}</div></div><div><span class="status">${esc(o.status)}</span> <b style="margin-left:8px">${fmt(o.total)}</b></div></div><div class="section">${(o.items||[]).map(i=>`<div class="line"><span>${esc(i.name)} × ${i.quantity}</span><b>${fmt(i.price*i.quantity)}</b></div>`).join('')}</div><div class="section"><div class="eyebrow">HISTORIQUE</div>${(o.history||[]).map(h=>`<div class="line"><span>${esc(h.status)}</span><span class="muted">${dt(h.at)}</span></div>`).join('')}</div></div>`).join('')||'<div class="panel muted">Aucune commande pour cette recherche.</div>'}$('#histSearch').onclick=load;$('#histReset').onclick=()=>{$('#histQ').value='';$('#histGroup').value='';load()};$('#histQ').addEventListener('keydown',e=>{if(e.key==='Enter')load()});await load()}
async function groupsView(c){const rows=await api('groups');c.innerHTML=`<div class="section-head"><h3>Groupes</h3>${can('groups.edit')?'<button id="newGroup" class="btn gold">+ Groupe</button>':''}</div><div class="cards">${rows.map(g=>`<div class="panel"><div class="line"><b>${esc(g.name)}</b><span class="status">${esc(g.status||'')}</span></div><p class="muted">Relation : ${esc(g.relation||'—')}<br>Leader : ${esc(g.leader||'—')}<br>Contacts : ${esc((g.contacts||[]).join(' • ')||'—')}</p><p>${esc(g.notes||'')}</p>${can('groups.edit')?`<button class="btn edit-group" data-id="${g.id}">Modifier</button> <button class="btn danger delete-group" data-id="${g.id}">Supprimer</button>`:''}</div>`).join('')}</div>`;function form(g){const d=modal(`<h2>${g?'Modifier':'Ajouter'} un groupe</h2><form class="stack"><input class="input" name="name" value="${esc(g?.name||'')}" placeholder="Nom" required><input class="input" name="leader" value="${esc(g?.leader||'')}" placeholder="Leader"><input class="input" name="relation" value="${esc(g?.relation||'Neutre')}" placeholder="Relation"><input class="input" name="status" value="${esc(g?.status||'Actif')}" placeholder="Statut"><textarea class="input" name="contacts" placeholder="Contacts, un par ligne">${esc((g?.contacts||[]).join('\n'))}</textarea><textarea class="input" name="notes" placeholder="Notes">${esc(g?.notes||'')}</textarea><button class="btn gold">Enregistrer</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),data={id:g?.id,name:f.get('name'),leader:f.get('leader'),relation:f.get('relation'),status:f.get('status'),contacts:parsePhones(f.get('contacts')),notes:f.get('notes')};await api('groups',g?'PUT':'POST',data);d.remove();groupsView(c)}}$('#newGroup')?.addEventListener('click',()=>form());$$('.edit-group').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.id)));$$('.delete-group').forEach(b=>b.onclick=async()=>{const g=rows.find(x=>x.id===b.dataset.id);if(!confirm(`Supprimer le groupe ${g?.name||''} ?`))return;await api('groups?id='+encodeURIComponent(b.dataset.id),'DELETE');toast('Groupe supprimé');groupsView(c)})}
async function financeView(c){const f=await api('finance');c.innerHTML=`<div class="grid stats"><div class="panel stat"><span>Cash global</span><b>${fmt(f.cash)}</b></div></div>${can('finance.edit')?`<div class="section panel"><form id="cashForm" class="line wrap"><input class="input" style="max-width:180px" type="number" name="amount" placeholder="+ / - montant" required><input class="input" style="max-width:360px" name="reason" placeholder="Motif" required><button class="btn gold">Valider</button></form></div>`:''}<div class="section table-wrap"><table><thead><tr><th>Date</th><th>Montant</th><th>Motif</th><th>Réalisé par</th></tr></thead><tbody>${f.transactions.map(t=>`<tr><td>${dt(t.createdAt)}</td><td><b>${fmt(t.amount)}</b></td><td>${esc(t.reason)}</td><td>${esc(t.actorName||'Système')}${t.actorUsername?`<div class="muted">@${esc(t.actorUsername)}</div>`:''}</td></tr>`).join('')}</tbody></table></div>`;$('#cashForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('finance','POST',{amount:Number(f.get('amount')),reason:f.get('reason')});toast('Cash mis à jour');financeView(c)})}
async function catalogView(c){const [cats,prods,roles]=await Promise.all([api('categories'),api('products'),api('roles')]);const sorted=[...cats].sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0));c.innerHTML=`<div class="section-head"><div><h3>Stock</h3><p class="muted">Choisis une catégorie pour afficher uniquement les objets concernés.</p></div>${isSuper()?'<button id="newProd" class="btn gold">+ Objet</button>':''}</div><div class="stock-tabs"><button class="tab active" data-stockcat="">Tout</button>${sorted.map(x=>`<button class="tab" data-stockcat="${x.id}">${esc(x.icon||'◆')} ${esc(x.name)}</button>`).join('')}${can('categories.edit')?'<button id="newCat" class="tab goldish">+ Catégorie</button>':''}</div><div id="stockSummary" class="grid stats section"></div><div id="stockGrid" class="product-grid"></div>`;function render(catId=''){const rows=prods.filter(p=>!catId||p.categoryId===catId);$('#stockSummary').innerHTML=`<div class="panel stat"><span>Objets affichés</span><b>${rows.length}</b></div><div class="panel stat"><span>Unités en stock</span><b>${rows.reduce((s,p)=>s+Number(p.stock||0),0)}</b></div><div class="panel stat"><span>Stock faible</span><b>${rows.filter(p=>Number(p.stock)<=Number(p.minStock||0)).length}</b></div>`;$('#stockGrid').innerHTML=rows.map(p=>{const cat=cats.find(x=>x.id===p.categoryId);const low=Number(p.stock)<=Number(p.minStock||0);return `<div class="product-card ${low?'low-stock':''}">${p.image?`<div class="product-img"><img src="${p.image}" alt=""></div>`:''}<div class="line"><b>${esc(p.name)}</b><span class="pill">${esc(cat?.name||'Sans catégorie')}</span></div><p class="muted">${esc(p.description||'')}</p><div class="line"><span>Stock</span><b>${p.stock}</b></div><div class="line"><span>Vente</span><b>${fmt(p.sellPrice)}</b></div>${low?'<div class="status danger">Stock faible</div>':''}${isSuper()?`<button class="btn small edit-prod" data-id="${p.id}" style="margin-top:10px">Modifier</button>`:''}</div>`}).join('')||'<div class="panel muted">Aucun objet dans cette catégorie.</div>';$$('.edit-prod').forEach(b=>b.onclick=()=>productModal(c,cats,prods.find(p=>p.id===b.dataset.id)))}$$('[data-stockcat]').forEach(b=>b.onclick=()=>{$$('[data-stockcat]').forEach(x=>x.classList.toggle('active',x===b));render(b.dataset.stockcat)});$('#newCat')?.addEventListener('click',()=>categoryModal(c,null,roles));if(can('categories.edit'))$$('[data-stockcat]').forEach(b=>b.addEventListener('dblclick',()=>{const cat=cats.find(x=>x.id===b.dataset.stockcat);if(cat)categoryModal(c,cat,roles)}));$('#newProd')?.addEventListener('click',()=>productModal(c,cats,null));render()}
function categoryModal(c,cat,roles){const d=modal(`<h2>${cat?'Modifier':'Nouvelle'} catégorie</h2><form class="stack"><label>Nom<input class="input" name="name" value="${esc(cat?.name||'')}" required></label><div class="split"><label>Icône<input class="input" name="icon" value="${esc(cat?.icon||'◆')}"></label><label>Couleur<input class="input" type="color" name="color" value="${esc(cat?.color||'#D4AF37')}"></label></div><div class="split"><label>Ordre<input class="input" type="number" name="sortOrder" value="${cat?.sortOrder??0}"></label><label>Mise en page<select class="input" name="layoutCols"><option value="2" ${cat?.layoutCols===2?'selected':''}>2 colonnes — grandes cartes</option><option value="3" ${!cat||cat?.layoutCols===3?'selected':''}>3 colonnes — standard</option><option value="4" ${cat?.layoutCols===4?'selected':''}>4 colonnes — compact</option></select></label></div><label>Accès<select class="input" name="visibility"><option value="client" ${cat?.visibility==='client'?'selected':''}>Clients</option><option value="member" ${cat?.visibility==='member'?'selected':''}>Membres Black Ace</option><option value="all" ${cat?.visibility==='all'?'selected':''}>Tout le monde</option><option value="roles" ${cat?.visibility==='roles'?'selected':''}>Rôles spécifiques</option></select></label><div class="perm-box"><h4>Rôles autorisés si « rôles spécifiques »</h4><div class="perm-grid">${roles.filter(r=>r.slug!=='super-admin').map(r=>`<label class="check"><input type="checkbox" name="roleId" value="${r.id}" ${(cat?.roleIds||[]).includes(r.id)?'checked':''}><span>${esc(r.name)}</span></label>`).join('')}</div></div><label>Image<input class="input" type="file" name="img" accept="image/*"></label><label class="check"><input type="checkbox" name="active" ${cat?.active!==false?'checked':''}> Catégorie active</label><button class="btn gold">Enregistrer</button></form>${cat?'<button id="deleteCat" class="btn danger" style="margin-top:10px">Supprimer la catégorie</button>':''}`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),img=f.get('img');await api('categories',cat?'PUT':'POST',{id:cat?.id,name:f.get('name'),icon:f.get('icon'),color:f.get('color'),sortOrder:Number(f.get('sortOrder')),layoutCols:Number(f.get('layoutCols')),visibility:f.get('visibility'),roleIds:f.getAll('roleId'),active:f.get('active')==='on',image:img?.size?await fileToDataUrl(img):(cat?.image||'')});d.remove();catalogView(c)};$('#deleteCat',d)?.addEventListener('click',async()=>{if(!confirm('Supprimer cette catégorie ?'))return;await api('categories?id='+encodeURIComponent(cat.id),'DELETE');d.remove();catalogView(c)})}
function productModal(c,cats,p){const d=modal(`<h2>${p?'Modifier':'Nouvel'} objet</h2><form class="stack"><input class="input" name="name" value="${esc(p?.name||'')}" placeholder="Nom" required><textarea class="input" name="description" placeholder="Description">${esc(p?.description||'')}</textarea><select class="input" name="categoryId">${cats.map(x=>`<option value="${x.id}" ${p?.categoryId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="split"><input class="input" type="number" name="stock" value="${p?.stock??0}" placeholder="Stock"><input class="input" type="number" name="minStock" value="${p?.minStock??0}" placeholder="Stock mini"></div><div class="split"><input class="input" type="number" name="sellPrice" value="${p?.sellPrice??0}" placeholder="Prix vente"><input class="input" type="number" name="buybackPrice" value="${p?.buybackPrice??0}" placeholder="Prix rachat"></div><input class="input" type="file" name="img" accept="image/*"><button class="btn gold">Enregistrer</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),img=f.get('img');await api('products',p?'PUT':'POST',{id:p?.id,name:f.get('name'),description:f.get('description'),categoryId:f.get('categoryId'),stock:Number(f.get('stock')),minStock:Number(f.get('minStock')),sellPrice:Number(f.get('sellPrice')),buybackPrice:Number(f.get('buybackPrice')),image:img?.size?await fileToDataUrl(img):(p?.image||''),visibility:'client'});d.remove();catalogView(c)}}
async function announcementsView(c){const rows=(await api('announcements')).sort((a,b)=>(Number(!!b.pinned)-Number(!!a.pinned))||String(b.createdAt).localeCompare(String(a.createdAt)));c.innerHTML=`<div class="section-head"><h3>Annonces</h3>${can('announcements.edit')?'<button id="newAnn" class="btn gold">+ Annonce</button>':''}</div><div class="cards">${rows.map(a=>`<div class="panel">${a.image?`<div class="product-img"><img src="${a.image}" alt=""></div>`:''}<h3>${esc(a.title)}</h3><p>${esc(a.body)}</p><span class="muted">${dt(a.createdAt)}</span></div>`).join('')}</div>`;$('#newAnn')?.addEventListener('click',()=>{const d=modal(`<h2>Nouvelle annonce</h2><form class="stack"><input class="input" name="title" placeholder="Titre" required><textarea class="input" name="body" placeholder="Message"></textarea><select class="input" name="visibility"><option value="all">Tout le monde</option><option value="client">Clients</option><option value="member">Membres</option><option value="admin">Admins</option></select><label class="check"><input type="checkbox" name="pinned"> Épingler</label><input class="input" type="file" name="img" accept="image/*"><button class="btn gold">Publier</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),img=f.get('img');await api('announcements','POST',{title:f.get('title'),body:f.get('body'),visibility:f.get('visibility'),pinned:f.get('pinned')==='on',image:img?.size?await fileToDataUrl(img):''});d.remove();announcementsView(c)}})}

async function messages(c){let convs=await api('conversations'),selected=convs[0]?.id||null,lastSig='';c.innerHTML=`<div class="messages"><div class="panel"><div class="section-head"><h3>Conversations</h3></div>${!isClient()?`<div class="stack" style="margin-bottom:12px"><input id="contactSearch" class="input" placeholder="Rechercher client ou groupe"><div id="contactResults"></div></div>`:''}<div id="convList" class="message-list"></div></div><div class="panel chat"><div id="chatHead" class="section-head"><h3>Messages</h3></div><div id="chatLog" class="chat-log"></div><form id="chatForm" class="chat-form"><input class="input" name="text" placeholder="Écrire un message…" autocomplete="off"><button class="btn gold">Envoyer</button></form></div></div>`;function renderList(){const el=$('#convList');const html=convs.map(v=>`<button class="conv ${v.id===selected?'active':''}" data-id="${v.id}"><b>${esc(v.title)}</b><div class="muted">${esc(v.subtitle||'')}</div>${v.messages?.length?`<small class="muted">${esc(v.messages[v.messages.length-1].text).slice(0,42)}</small>`:''}</button>`).join('')||'<p class="muted">Aucune conversation.</p>';if(el.innerHTML!==html)el.innerHTML=html;$$('.conv',el).forEach(b=>b.onclick=()=>{selected=b.dataset.id;renderList();renderChat(true)})}function renderChat(force=false){const v=convs.find(x=>x.id===selected);const sig=JSON.stringify(v?.messages?.map(m=>[m.id,m.createdAt,m.text])||[]);$('#chatHead').innerHTML=v?`<div><h3 style="margin:0">${esc(v.title)}</h3><div class="muted">${esc(v.subtitle||'')}</div></div>`:'<h3>Messages</h3>';if(!force&&sig===lastSig)return;lastSig=sig;const log=$('#chatLog'),nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<90;log.innerHTML=v?(v.messages||[]).map(m=>`<div class="bubble ${m.senderId===state.user.id?'me':''}">${esc(m.text)}<small>${esc(m.senderName)} • ${dt(m.createdAt)}</small></div>`).join(''):'<p class="muted">Sélectionne une conversation.</p>';if(force||nearBottom)requestAnimationFrame(()=>log.scrollTo({top:log.scrollHeight,behavior:'smooth'}))}renderList();renderChat(true);if(!isClient()){let timer;$('#contactSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=$('#contactSearch').value;const rows=await api('contacts?q='+encodeURIComponent(q));$('#contactResults').innerHTML=rows.slice(0,12).map(x=>`<button class="conv start-contact" data-type="${x.type}" data-id="${x.id}"><b>${esc(x.name)}</b><div class="muted">${esc(x.subtitle||x.group||'')}</div></button>`).join('');$$('.start-contact').forEach(b=>b.onclick=async()=>{const v=await api('conversations','POST',{startType:b.dataset.type,startId:b.dataset.id});convs=await api('conversations');selected=v.id;lastSig='';$('#contactSearch').value='';$('#contactResults').innerHTML='';renderList();renderChat(true)})},180)}}$('#chatForm').onsubmit=async e=>{e.preventDefault();const input=$('input[name="text"]',e.currentTarget),text=String(input.value||'').trim();if(!text)return;if(selected)await api('conversations','POST',{conversationId:selected,text});else if(isClient())await api('conversations','POST',{text});else return toast('Choisis un contact');input.value='';convs=await api('conversations');selected=selected||convs[0]?.id;lastSig='';renderList();renderChat(true);input.focus()};const poll=setInterval(async()=>{try{const n=await api('conversations');const oldSelected=selected;convs=n;if(selected&&!convs.some(x=>x.id===selected))selected=convs[0]?.id;renderList();renderChat(oldSelected!==selected)}catch{}},1500);state.cleanup=()=>clearInterval(poll)}

function mapWidget(root,{editable=true,x=null,y=null,onChange=()=>{}}={}){
  root.innerHTML=`<div class="map-wrap"><div class="map-toolbar"><span class="pill">Carte GTA locale 8K • zoom HD</span><span class="map-coord">${x==null?'Aucun point':`X ${Number(x).toFixed(4)}% • Y ${Number(y).toFixed(4)}%`}</span><span class="muted">${editable?'Clique pour placer le rendez-vous • molette / boutons + − • glisse pour déplacer':'Molette / boutons + − • glisse pour déplacer'}</span></div><div class="local-gta-map"><div class="local-map-stage"><img src="/gta-map-8k.jpg" alt="Carte GTA V"><div class="local-map-marker"></div></div><div class="local-map-controls"><button type="button" class="map-plus" aria-label="Zoomer">+</button><button type="button" class="map-minus" aria-label="Dézoomer">−</button><button type="button" class="map-reset" aria-label="Réinitialiser">⌂</button></div></div></div>`;
  const box=$('.local-gta-map',root),stage=$('.local-map-stage',root),img=$('img',stage),marker=$('.local-map-marker',stage),coord=$('.map-coord',root);
  let scale=1,tx=0,ty=0,minScale=1,maxScale=8,dragging=false,moved=false,startX=0,startY=0,startTx=0,startTy=0;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function baseSize(){return {w:box.clientWidth,h:box.clientHeight}}
  function clampPan(){const {w,h}=baseSize();const sw=w*scale,sh=h*scale;tx=clamp(tx,Math.min(0,w-sw),0);ty=clamp(ty,Math.min(0,h-sh),0)}
  function apply(){clampPan();stage.style.transform=`translate3d(${tx}px,${ty}px,0) scale(${scale})`;marker.style.display=(x==null||y==null)?'none':'block';if(x!=null&&y!=null){marker.style.left=`${Number(x)}%`;marker.style.top=`${Number(y)}%`;coord.textContent=`X ${Number(x).toFixed(4)}% • Y ${Number(y).toFixed(4)}%`}}
  function zoomAt(clientX,clientY,factor){const r=box.getBoundingClientRect();const px=clientX-r.left,py=clientY-r.top;const old=scale;const next=clamp(old*factor,minScale,maxScale);if(next===old)return;const ix=(px-tx)/old,iy=(py-ty)/old;scale=next;tx=px-ix*next;ty=py-iy*next;apply()}
  function reset(){scale=1;tx=0;ty=0;apply()}
  function setPointFromClient(clientX,clientY){const r=box.getBoundingClientRect();const ix=(clientX-r.left-tx)/scale,iy=(clientY-r.top-ty)/scale;const px=clamp(ix/r.width*100,0,100),py=clamp(iy/r.height*100,0,100);x=px;y=py;apply();onChange(x,y)}
  box.addEventListener('wheel',e=>{e.preventDefault();zoomAt(e.clientX,e.clientY,e.deltaY<0?1.25:0.8)},{passive:false});
  box.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;moved=false;startX=e.clientX;startY=e.clientY;startTx=tx;startTy=ty;box.setPointerCapture?.(e.pointerId);box.classList.add('dragging')});
  box.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;tx=startTx+dx;ty=startTy+dy;apply()});
  box.addEventListener('pointerup',e=>{if(!dragging)return;dragging=false;box.classList.remove('dragging');box.releasePointerCapture?.(e.pointerId);if(editable&&!moved)setPointFromClient(e.clientX,e.clientY)});
  box.addEventListener('pointercancel',()=>{dragging=false;box.classList.remove('dragging')});
  $('.map-plus',root).onclick=()=>{const r=box.getBoundingClientRect();zoomAt(r.left+r.width/2,r.top+r.height/2,1.35)};
  $('.map-minus',root).onclick=()=>{const r=box.getBoundingClientRect();zoomAt(r.left+r.width/2,r.top+r.height/2,0.74)};
  $('.map-reset',root).onclick=reset;
  img.addEventListener('load',()=>apply(),{once:true});
  window.addEventListener('resize',apply,{passive:true});
  apply();
  return {get:()=>({x,y}),set:(nx,ny)=>{x=nx;y=ny;apply()}};
}

async function appointments(c){let rows=await api('appointments');if(isClient())return clientAppointments(c,rows);memberAppointments(c,rows)}
function clientAppointments(c,rows){c.innerHTML=`<div class="section-head"><div><h2 style="margin:0">Mes rendez-vous</h2><p class="muted">Demande un rendez-vous. Une fois planifié par Black Ace, confirme si tu es disponible.</p></div><button id="askRdv" class="btn gold">Demander un RDV</button></div><div class="stack">${rows.map(r=>`<div class="panel"><div class="line wrap"><div><b>${esc(r.subject)}</b><div class="muted">${r.scheduledAt?`📅 ${dt(r.scheduledAt)}`:esc(r.availability||'En attente de Black Ace')}</div></div><span class="status ${r.status==='Confirmé'?'ok':''}">${esc(r.status)}</span></div>${r.locationLabel?`<p><b>Lieu :</b> ${esc(r.locationLabel)}</p>`:''}${r.note?`<p class="muted">${esc(r.note)}</p>`:''}${r.status==='Confirmé'&&r.scheduledAt?`<div class="panel flat"><div class="line wrap"><div><b>Disponibilité</b><div class="muted">Peux-tu être présent à ${dt(r.scheduledAt)} ?</div></div><span class="status ${r.clientResponse==='Oui'?'ok':r.clientResponse==='Non'?'danger':''}">${esc(r.clientResponse||'En attente')}</span></div><div class="line wrap" style="margin-top:10px"><button class="btn gold rdv-response" data-id="${r.id}" data-response="Oui">✓ Oui, disponible</button><button class="btn danger rdv-response" data-id="${r.id}" data-response="Non">✕ Non, indisponible</button></div></div>`:''}${r.mapX!=null?`<div class="section" id="map-${r.id}"></div>`:''}</div>`).join('')||'<div class="panel muted">Aucun rendez-vous.</div>'}`;rows.filter(r=>r.mapX!=null).forEach(r=>mapWidget($('#map-'+r.id),{editable:false,x:r.mapX,y:r.mapY}));$$('.rdv-response').forEach(b=>b.onclick=async()=>{await api('appointments','PUT',{id:b.dataset.id,clientResponse:b.dataset.response});toast('Disponibilité enregistrée');appointments(c)});$('#askRdv').onclick=()=>{const d=modal(`<h2>Demander un rendez-vous</h2><form class="stack"><input class="input" name="subject" placeholder="Motif" required><textarea class="input" name="availability" placeholder="Tes disponibilités"></textarea><textarea class="input" name="note" placeholder="Informations utiles"></textarea><button class="btn gold">Envoyer la demande</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('appointments','POST',{subject:f.get('subject'),availability:f.get('availability'),note:f.get('note')});d.remove();toast('Demande envoyée');cleanup();appointments(c)}};const signature=JSON.stringify(rows);const timer=setInterval(async()=>{try{const n=await api('appointments');if(JSON.stringify(n)!==signature){clearInterval(timer);clientAppointments(c,n)}}catch{}},2500);state.cleanup=()=>clearInterval(timer)}
async function memberAppointments(c,rows){const contacts=await api('contacts?q=');const clients=contacts.filter(x=>x.type==='user');const active=rows.filter(r=>!['Terminé','Annulé'].includes(r.status));c.innerHTML=`<div class="section-head"><div><h2 style="margin:0">Rendez-vous</h2><p class="muted">Calendrier, position et disponibilité client au même endroit.</p></div><div class="line wrap"><button id="historyRdv" class="btn">Historique RDV</button><button id="newRdv" class="btn gold">+ Prendre un RDV</button></div></div><div class="split"><div><div class="panel" id="calendarBox"></div><div class="section stack" id="rdvList"></div></div><div class="panel"><div class="eyebrow">DÉTAIL DU RDV</div><div id="rdvDetail" class="muted">Clique sur un rendez-vous du calendrier ou de la liste.</div><div id="sideMap" class="section"></div></div></div>`;function showDetail(r){if(!r)return;$('#rdvDetail').innerHTML=`<h3>${esc(r.clientName)} — ${esc(r.subject)}</h3><div class="cred-grid"><div class="cred"><small>Groupe</small><b>${esc(r.groupName||'Sans groupe')}</b></div><div class="cred"><small>Date / heure</small><b>${dt(r.scheduledAt)}</b></div><div class="cred"><small>Disponibilité</small><b>${esc(r.clientResponse||'En attente')}</b></div></div><p><b>Lieu :</b> ${esc(r.locationLabel||'—')}</p><p class="muted">${esc(r.note||'')}</p><button id="editSelectedRdv" class="btn gold">Modifier ce RDV</button>`;const box=$('#sideMap');if(r.mapX!=null)mapWidget(box,{editable:false,x:r.mapX,y:r.mapY});else box.innerHTML='<p class="muted">Aucune position définie.</p>';$('#editSelectedRdv').onclick=()=>editRdv(r)}renderCalendar($('#calendarBox'),active,showDetail);function list(){const el=$('#rdvList');el.innerHTML=active.map(r=>`<button class="conv rdv-row" data-id="${r.id}"><div class="line"><b>${esc(r.clientName)} • ${esc(r.subject)}</b><span class="status ${r.status==='Confirmé'?'ok':''}">${esc(r.status)}</span></div><div class="muted">${esc(r.groupName||'Sans groupe')} • ${r.scheduledAt?dt(r.scheduledAt):esc(r.availability||'À planifier')} • Dispo: ${esc(r.clientResponse||'En attente')}</div></button>`).join('')||'<div class="panel muted">Aucun RDV actif.</div>';$$('.rdv-row').forEach(b=>b.onclick=()=>showDetail(active.find(x=>x.id===b.dataset.id)))}list();function createModal(){const d=modal(`<h2>Prendre un rendez-vous</h2><form class="stack"><select class="input" name="clientId" required><option value="">Choisir un client</option>${clients.map(x=>`<option value="${x.id}">${esc(x.name)} • ${esc(x.group||'')}</option>`).join('')}</select><input class="input" name="subject" placeholder="Motif" required><input class="input" type="datetime-local" name="scheduledAt" required><div class="panel flat"><b>Disponibilité client</b><div class="muted">Le client répondra lui-même Oui ou Non depuis son compte après réception du rendez-vous.</div></div><input class="input" name="locationLabel" placeholder="Nom du lieu"><textarea class="input" name="note" placeholder="Note"></textarea><div id="rdvMap"></div><button class="btn gold">Confirmer le rendez-vous</button></form>`);let pos={x:null,y:null};mapWidget($('#rdvMap',d),{editable:true,onChange:(x,y)=>pos={x,y}});$('form',d).onsubmit=async e=>{e.preventDefault();if(pos.x==null)return toast('Place un point sur la carte');const f=new FormData(e.currentTarget);const r=await api('appointments','POST',{clientId:f.get('clientId'),subject:f.get('subject'),scheduledAt:f.get('scheduledAt'),locationLabel:f.get('locationLabel'),note:f.get('note'),mapX:pos.x,mapY:pos.y});d.remove();toast('RDV créé');appointments(c)}}function editRdv(r){const d=modal(`<h2>${esc(r.clientName)} — ${esc(r.subject)}</h2><form class="stack"><label>Statut<select class="input" name="status"><option ${r.status==='Demandé'?'selected':''}>Demandé</option><option ${r.status==='Confirmé'?'selected':''}>Confirmé</option><option ${r.status==='Terminé'?'selected':''}>Terminé</option><option ${r.status==='Annulé'?'selected':''}>Annulé</option></select></label><div class="panel flat"><b>Disponibilité client : ${esc(r.clientResponse||'En attente')}</b><div class="muted">Seul le client peut confirmer Oui ou Non. Si tu modifies la date, l’heure ou la position, sa réponse sera remise en attente.</div></div><input class="input" type="datetime-local" name="scheduledAt" value="${r.scheduledAt?esc(String(r.scheduledAt).slice(0,16)):''}"><input class="input" name="locationLabel" value="${esc(r.locationLabel||'')}" placeholder="Nom du lieu"><textarea class="input" name="note">${esc(r.note||'')}</textarea><div id="editMap"></div><button class="btn gold">Enregistrer</button></form>`);let pos={x:r.mapX,y:r.mapY};mapWidget($('#editMap',d),{editable:true,x:r.mapX,y:r.mapY,onChange:(x,y)=>pos={x,y}});$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('appointments','PUT',{id:r.id,status:f.get('status'),scheduledAt:f.get('scheduledAt'),locationLabel:f.get('locationLabel'),note:f.get('note'),mapX:pos.x,mapY:pos.y});d.remove();toast('RDV mis à jour');appointments(c)}}$('#newRdv').onclick=createModal;$('#historyRdv').onclick=async()=>{const d=modal(`<h2>Historique de tous les rendez-vous</h2><input id="rdvHistQ" class="input" placeholder="Rechercher client, groupe, lieu…"><div id="rdvHistRows" class="stack section"></div>`);async function draw(){const q=$('#rdvHistQ',d).value.trim();const rr=await api('appointment-history?q='+encodeURIComponent(q));$('#rdvHistRows',d).innerHTML=rr.map(r=>`<div class="panel flat"><div class="line"><b>${esc(r.clientName)} • ${esc(r.groupName)}</b><span class="status">${esc(r.status)}</span></div><div class="muted">${dt(r.scheduledAt)} • ${esc(r.locationLabel||'—')} • ${esc(r.subject)}</div></div>`).join('')||'<p class="muted">Aucun historique.</p>'}$('#rdvHistQ',d).oninput=()=>draw();draw()}}
function renderCalendar(root,rows,onSelect=()=>{}){let cur=new Date();cur=new Date(cur.getFullYear(),cur.getMonth(),1);function draw(){const y=cur.getFullYear(),m=cur.getMonth(),first=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),prev=new Date(y,m,0).getDate();const cells=[];for(let i=0;i<42;i++){let day,month=m,year=y,other=false;if(i<first){day=prev-first+i+1;month=m-1;other=true}else if(i>=first+days){day=i-first-days+1;month=m+1;other=true}else day=i-first+1;const dd=new Date(year,month,day),key=`${dd.getFullYear()}-${String(dd.getMonth()+1).padStart(2,'0')}-${String(dd.getDate()).padStart(2,'0')}`;const ev=rows.filter(r=>r.scheduledAt&&String(r.scheduledAt).slice(0,10)===key);cells.push(`<div class="cal-day ${other?'other':''}"><span class="num">${day}</span>${ev.slice(0,4).map(e=>`<button type="button" class="cal-event" data-rdv="${e.id}">${esc(e.clientName)} • ${String(e.scheduledAt).slice(11,16)}</button>`).join('')}</div>`)}root.innerHTML=`<div class="calendar-head"><button class="btn small" id="prevCal">←</button><b>${cur.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</b><button class="btn small" id="nextCal">→</button></div><div class="calendar section"><div class="cal-name">Lun</div><div class="cal-name">Mar</div><div class="cal-name">Mer</div><div class="cal-name">Jeu</div><div class="cal-name">Ven</div><div class="cal-name">Sam</div><div class="cal-name">Dim</div>${cells.join('')}</div>`;$('#prevCal',root).onclick=()=>{cur=new Date(y,m-1,1);draw()};$('#nextCal',root).onclick=()=>{cur=new Date(y,m+1,1);draw()};$$('[data-rdv]',root).forEach(b=>b.onclick=()=>onSelect(rows.find(r=>r.id===b.dataset.rdv)))}draw()}
async function admin(c){const tabs=[];if(can('users.view'))tabs.push(['users','Comptes']);if(can('users.info.view'))tabs.push(['directory','Infos comptes']);if(can('roles.edit'))tabs.push(['roles','Rôles']);if(can('widgets.manage'))tabs.push(['widgets','Widgets']);if(can('logs.view'))tabs.push(['logs','Logs']);if(can('settings.edit'))tabs.push(['settings','Paramètres']);if(!tabs.length){c.innerHTML='<div class="panel">Accès refusé.</div>';return}c.innerHTML=`<div class="tabs">${tabs.map((x,i)=>`<button class="tab ${i===0?'active':''}" data-atab="${x[0]}">${x[1]}</button>`).join('')}</div><div id="adminBody"></div>`;const b=$('#adminBody');async function load(t){$$('[data-atab]').forEach(x=>x.classList.toggle('active',x.dataset.atab===t));if(t==='users')await usersView(b);if(t==='directory')await userDirectoryView(b);if(t==='roles')await rolesView(b);if(t==='widgets')await widgetsView(b);if(t==='logs')await logsView(b);if(t==='settings')await settingsView(b)}$$('[data-atab]').forEach(x=>x.onclick=()=>load(x.dataset.atab));await load(tabs[0][0])}
async function userDirectoryView(c){c.innerHTML=`<div class="section-head"><div><h3>Informations comptes</h3><p class="muted">Les mots de passe connus ne sont visibles qu'avec la permission dédiée.</p></div></div><div class="panel"><input id="dirQ" class="input" placeholder="Rechercher un nom, groupe ou rôle"></div><div id="dirRows" class="section"></div>`;async function load(){const q=$('#dirQ').value.trim();const data=await api('user-directory'+(q?'?q='+encodeURIComponent(q):''));const rows=data.rows||[];$('#dirRows').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Nom</th><th>Groupe</th><th>Rôle</th><th>Statut</th><th>Commandes</th><th>Dernière connexion</th>${data.showPasswords?'<th>Mot de passe</th>':''}</tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.displayName)}</b></td><td>${esc(x.groupName)}</td><td>${esc(x.roleName)}</td><td>${esc(x.status)}</td><td>${x.orderCount}</td><td>${dt(x.lastLogin)}</td>${data.showPasswords?`<td><code>${esc(x.passwordLabel||'Non disponible')}</code></td>`:''}</tr>`).join('')}</tbody></table></div>`}let t;$('#dirQ').addEventListener('input',()=>{clearTimeout(t);t=setTimeout(load,220)});await load()}
async function usersView(c){const [rows,roles,groups]=await Promise.all([api('users'),api('roles'),api('groups').catch(()=>[])]);c.innerHTML=`<div class="section-head"><div><h3>Comptes</h3><p class="muted">Les comptes vierges restent invisibles dans Messages tant qu'ils ne sont pas attribués.</p></div><div><button id="blankUsers" class="btn">+ Comptes vierges</button> <button id="newUser" class="btn gold">+ Compte</button></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Login</th><th>Nom</th><th>Téléphones</th><th>Rôle</th><th>Groupe</th><th>État</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><code>${esc(u.accountCode||u.id)}</code></td><td>@${esc(u.username)}</td><td>${esc(u.displayName)}</td><td>${esc((u.phones||[]).join(' • ')||'—')}</td><td>${esc(u.roleName)}</td><td>${esc(u.groupName||'—')}</td><td>${u.assigned===false?'<span class="status muted">Vierge</span>':'<span class="status ok">Attribué</span>'}</td><td><button class="btn small edit-user" data-id="${u.id}">Modifier</button></td></tr>`).join('')}</tbody></table></div>`;$('#blankUsers').onclick=()=>{const d=modal(`<h2>Créer des comptes vierges</h2><p class="muted">Mot de passe commun : <b>1234</b>. Chaque compte aura un ID et un nom d'utilisateur uniques. Ils seront cachés de la messagerie jusqu'à attribution.</p><form class="stack"><input class="input" type="number" min="1" max="100" name="count" value="5"><button class="btn gold">Créer</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const made=await api('blank-users','POST',{count:Number(f.get('count'))});d.remove();toast(`${made.length} compte(s) créé(s)`);usersView(c)}};function form(x){const allowed=roles.filter(r=>r.slug!=='super-admin'||x?.id==='user_admin');const d=modal(`<h2>${x?'Modifier':'Créer'} un compte</h2><form class="stack"><input class="input" name="accountCode" value="${esc(x?.accountCode||'')}" placeholder="ID compte (ex: BA-001)"><input class="input" name="username" value="${esc(x?.username||'')}" placeholder="Nom d'utilisateur" required><input class="input" name="displayName" value="${esc(x?.displayName||'')}" placeholder="Nom affiché" required><textarea class="input" name="phones" placeholder="Numéros, un par ligne">${esc((x?.phones||[]).join('\n'))}</textarea><input class="input" type="password" name="password" placeholder="${x?'Nouveau mot de passe (facultatif)':'Mot de passe'}"><select class="input" name="roleId">${allowed.map(r=>`<option value="${r.id}" ${x?.roleId===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><select class="input" name="groupId"><option value="">Sans groupe</option>${groups.map(g=>`<option value="${g.id}" ${x?.groupId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><input class="input" name="groupName" value="${esc(x?.groupName||'')}" placeholder="Nom du groupe client (modifiable)"><label class="check"><input type="checkbox" name="assigned" ${x?.assigned!==false?'checked':''}> Compte attribué / visible dans Messages</label><select class="input" name="status"><option value="active" ${x?.status!=='suspended'?'selected':''}>Actif</option><option value="suspended" ${x?.status==='suspended'?'selected':''}>Suspendu</option></select><button class="btn gold">Enregistrer</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),data={id:x?.id,accountCode:f.get('accountCode'),username:f.get('username'),displayName:f.get('displayName'),phones:parsePhones(f.get('phones')),password:f.get('password'),roleId:f.get('roleId'),groupId:f.get('groupId'),groupName:f.get('groupName'),assigned:f.get('assigned')==='on',status:f.get('status')};await api('users',x?'PUT':'POST',data);d.remove();usersView(c)}}$('#newUser').onclick=()=>form(null);$$('.edit-user').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.id)))}
async function rolesView(c){const rows=await api('roles');c.innerHTML=`<div class="section-head"><div><h3>Rôles & permissions</h3><p class="muted">Permissions regroupées par fonction pour être plus lisibles.</p></div><button id="newRole" class="btn gold">+ Rôle</button></div><div class="cards">${rows.map(r=>`<div class="panel"><div class="line"><b>${esc(r.name)}</b>${r.slug==='super-admin'?'<span class="status">Unique</span>':''}</div><p class="muted">${Object.values(r.permissions||{}).filter(Boolean).length} permission(s)</p>${r.slug!=='super-admin'?`<button class="btn edit-role" data-id="${r.id}">Configurer</button>`:'<span class="muted">Rôle verrouillé</span>'}</div>`).join('')}</div>`;function form(r){const d=modal(`<h2>${r?'Modifier':'Créer'} un rôle</h2><form class="stack"><label>Nom du rôle<input class="input" name="name" value="${esc(r?.name||'')}" required></label><div class="perm-groups">${Object.entries(PERM_GROUPS).map(([g,ps])=>`<div class="perm-box"><h4>${esc(g)}</h4><div class="perm-grid">${ps.map(([p,l])=>`<label class="check"><input type="checkbox" name="perm" value="${p}" ${r?.permissions?.[p]?'checked':''}><span><b>${esc(l)}</b><br><span class="muted">${esc(p)}</span></span></label>`).join('')}</div></div>`).join('')}</div><button class="btn gold">Enregistrer le rôle</button></form>`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),permissions={};f.getAll('perm').forEach(p=>permissions[p]=true);await api('roles',r?'PUT':'POST',{id:r?.id,name:f.get('name'),permissions});d.remove();rolesView(c)}}$('#newRole').onclick=()=>form(null);$$('.edit-role').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.id)))}
async function widgetsView(c){const rows=await api('widgets');c.innerHTML=`<div class="section-head"><div><h3>Widgets dashboard</h3><p class="muted">Ajoute des cartes personnalisées aux dashboards.</p></div><button id="newWidget" class="btn gold">+ Widget</button></div><div class="cards">${rows.map(w=>`<div class="panel"><div class="muted">${esc(w.icon)} ${esc(w.audience)}</div><h3>${esc(w.title)}</h3><b style="font-size:24px;color:var(--gold)">${esc(w.value)}</b><p class="muted">${esc(w.subtitle||'')}</p><button class="btn small edit-widget" data-id="${w.id}">Modifier</button></div>`).join('')||'<div class="panel muted">Aucun widget.</div>'}`;function form(w){const d=modal(`<h2>${w?'Modifier':'Nouveau'} widget</h2><form class="stack"><input class="input" name="title" value="${esc(w?.title||'')}" placeholder="Titre" required><input class="input" name="value" value="${esc(w?.value||'')}" placeholder="Valeur (ex: Ouvert, 25%, 18h)"><input class="input" name="subtitle" value="${esc(w?.subtitle||'')}" placeholder="Sous-titre"><input class="input" name="icon" value="${esc(w?.icon||'◆')}" placeholder="Icône"><select class="input" name="audience"><option value="member" ${w?.audience==='member'?'selected':''}>Membres</option><option value="client" ${w?.audience==='client'?'selected':''}>Clients</option><option value="all" ${w?.audience==='all'?'selected':''}>Tout le monde</option></select><input class="input" type="number" name="sortOrder" value="${w?.sortOrder??0}" placeholder="Ordre"><button class="btn gold">Enregistrer</button></form>${w?'<button id="deleteWidget" class="btn danger" style="margin-top:10px">Supprimer</button>':''}`);$('form',d).onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('widgets',w?'PUT':'POST',{id:w?.id,title:f.get('title'),value:f.get('value'),subtitle:f.get('subtitle'),icon:f.get('icon'),audience:f.get('audience'),sortOrder:Number(f.get('sortOrder'))});d.remove();widgetsView(c)};$('#deleteWidget',d)?.addEventListener('click',async()=>{await api('widgets?id='+encodeURIComponent(w.id),'DELETE');d.remove();widgetsView(c)})}$('#newWidget').onclick=()=>form(null);$$('.edit-widget').forEach(b=>b.onclick=()=>form(rows.find(x=>x.id===b.dataset.id)))}
async function logsView(c){const users=await api('users');c.innerHTML=`<div class="section-head"><div><h3>Journal d'activité</h3><p class="muted">Chaque action indique le profil, la catégorie et le montant quand il y en a un.</p></div></div><div class="panel"><div class="line wrap"><input id="logQ" class="input" style="max-width:260px" placeholder="Rechercher action / profil / montant"><select id="logUser" class="input" style="max-width:240px"><option value="">Toutes les personnes</option>${users.map(u=>`<option value="${u.id}">${esc(u.displayName)} (@${esc(u.username)})</option>`).join('')}</select><select id="logEntity" class="input" style="max-width:220px"><option value="">Toutes les catégories</option><option value="user">Comptes</option><option value="order">Commandes</option><option value="appointment">Rendez-vous</option><option value="group">Groupes</option><option value="product">Objets</option><option value="category">Catégories</option><option value="finance">Finances</option><option value="role">Rôles</option><option value="widget">Widgets</option><option value="settings">Paramètres</option></select><button id="filterLogs" class="btn gold">Filtrer</button></div></div><div id="logsBody" class="section"></div>`;async function load(){const q=new URLSearchParams();if($('#logQ').value)q.set('q',$('#logQ').value);if($('#logUser').value)q.set('userId',$('#logUser').value);if($('#logEntity').value)q.set('entity',$('#logEntity').value);const rows=await api('logs?'+q.toString());const grouped={};rows.forEach(l=>(grouped[l.displayName]??=[]).push(l));$('#logsBody').innerHTML=Object.entries(grouped).map(([name,ls])=>`<div class="panel" style="margin-bottom:10px"><div class="section-head"><div><b>${esc(name)}</b><div class="muted">@${esc(ls[0]?.username||'')} • ${esc(ls[0]?.accountCode||'')}</div></div><span class="pill">${ls.length} action(s)</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Profil</th><th>Catégorie</th><th>Action</th><th>Montant</th><th>Détail</th></tr></thead><tbody>${ls.map(l=>`<tr><td>${dt(l.createdAt)}</td><td>${esc(l.displayName)}<br><span class="muted">@${esc(l.username||'')}</span></td><td>${esc(l.entity||'—')}</td><td>${esc(l.action)}</td><td>${l.amount!=null?`<b>${fmt(l.amount)}</b>`:'—'}</td><td>${esc(l.details||l.entityId||'—')}</td></tr>`).join('')}</tbody></table></div></div>`).join('')||'<div class="panel muted">Aucun log.</div>'}$('#filterLogs').onclick=load;await load()}
async function settingsView(c){const s=await api('settings');c.innerHTML=`<div class="panel"><form id="settingsForm" class="stack"><label>Nom de la tablette<input class="input" name="appName" value="${esc(s.appName)}"></label><label>Sous-titre<input class="input" name="tagline" value="${esc(s.tagline||'')}"></label><label>Initiales<input class="input" name="logoText" value="${esc(s.logoText||'BA')}"></label><label>Devise<input class="input" name="currency" value="${esc(s.currency||'$')}"></label><button class="btn gold">Enregistrer</button></form></div>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));await api('settings','PUT',data);state.settings={...state.settings,...data};toast('Paramètres enregistrés');shell()}}

boot();
